type Props = {
  links?: DjSocialLinks;
  /** Short label above icons on post-gig screens. */
  heading?: string;
};

/** Icon row for DJ social links — used on crowd post-gig / offline pages. */
export default function DjSocialIcons({ links, heading = "Follow on" }: Props) {
  const items = listSocialLinks(links);
  if (items.length === 0) return null;

  return (
    <div className="dj-social-icons">
      <p className="dj-social-icons-label">{heading}</p>
      <div className="dj-social-icons-row" role="list">
        {items.map((item) => (
          <a
            key={item.key}
            href={item.href}
            target="_blank"
            rel="noopener noreferrer"
            className="dj-social-icon-btn"
            aria-label={`${item.label} — ${displayName(item.raw)}`}
            title={item.label}
            role="listitem"
          >
            <SocialIcon platform={item.key} />
          </a>
        ))}
      </div>
    </div>
  );
}

function displayName(raw: string): string {
  return raw.replace(/^@/, "").replace(/^https?:\/\//, "");
}
